import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
import io
import os

# Set global seaborn style
sns.set_theme(style="whitegrid")
plt.rcParams['figure.figsize'] = (10, 6)
plt.rcParams['axes.titlesize'] = 14
plt.rcParams['axes.labelsize'] = 12

def df_to_html_table(df, **kwargs):
    return df.to_html(classes='table table-striped table-bordered', border=0, **kwargs)

def fig_to_base64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', transparent=True)
    buf.seek(0)
    data = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{data}"

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')
df.columns = df.columns.str.replace('^\ufeff', '', regex=True)

# 2. Compute KPIs
app_stats = df.groupby('App').agg(
    Avg_Star=('Star_Rating', 'mean'),
    Mean_Sentiment=('Sentiment_Polarity', 'mean'),
    Total_Reviews=('App', 'count')
).round(3).reset_index()
app_stats = app_stats.sort_values(by='Avg_Star', ascending=False)

# Theme Rates
theme_counts = df.groupby(['App', 'Review_Theme']).size().unstack(fill_value=0)
theme_totals = theme_counts.sum(axis=1)
theme_rates = theme_counts.div(theme_totals, axis=0) * 100
theme_rates['Complaint_Rate'] = theme_rates['Pricing/Subscription'] + theme_rates['Bugs/Performance'] + theme_rates['Accuracy/Logic Issues']
theme_rates_display = theme_rates.round(1).reset_index()

# Mismatch Rate
# Mismatch: Star >= 4 and Sentiment < 0 OR Star <= 2 and Sentiment > 0
df['Mismatch'] = ((df['Star_Rating'] >= 4) & (df['Sentiment_Polarity'] < 0)) | ((df['Star_Rating'] <= 2) & (df['Sentiment_Polarity'] > 0))
mismatch_rate = (df.groupby('App')['Mismatch'].mean() * 100).round(1).reset_index(name='Mismatch_Rate_%')
mismatch_rate = mismatch_rate.sort_values(by='Mismatch_Rate_%', ascending=False)

# Average Engagement
engagement_stats = df.groupby(['App', 'Review_Theme'])['Thumbs_Up_Count'].mean().unstack(fill_value=0).round(1).reset_index()

# Depth & Emotion
wc_by_star = df.groupby('Star_Rating')['Word_Count'].mean().round(1).reset_index()

# 3. Generate Visuals
# V1: Star vs Sentiment
fig1, ax1 = plt.subplots(figsize=(10, 6))
sns.scatterplot(data=app_stats, x='Avg_Star', y='Mean_Sentiment', hue='App', s=200, ax=ax1, palette='Set1')
for i in range(app_stats.shape[0]):
    ax1.text(app_stats.Avg_Star.iloc[i]+0.02, app_stats.Mean_Sentiment.iloc[i], app_stats.App.iloc[i], fontsize=10)
ax1.set_title("Average Star Rating vs. Mean Sentiment Polarity by App")
ax1.set_xlabel("Average Star Rating (1-5)")
ax1.set_ylabel("Mean VADER Sentiment Polarity (-1 to 1)")
fig1_b64 = fig_to_base64(fig1)

# V2: Theme Breakdown (Stacked Bar)
fig2, ax2 = plt.subplots(figsize=(12, 7))
plot_themes = theme_rates[['Accuracy/Logic Issues', 'Bugs/Performance', 'Pricing/Subscription', 'General']]
plot_themes.plot(kind='bar', stacked=True, ax=ax2, colormap='viridis')
ax2.set_title("Review Theme Distribution by Application (%)")
ax2.set_ylabel("Percentage of Reviews")
ax2.set_xlabel("Application")
plt.xticks(rotation=0)
plt.legend(title='Theme', bbox_to_anchor=(1.05, 1), loc='upper left')
fig2_b64 = fig_to_base64(fig2)

# V3: Mismatch Rate
fig3, ax3 = plt.subplots(figsize=(10, 6))
sns.barplot(data=mismatch_rate, x='App', y='Mismatch_Rate_%', ax=ax3, palette='Reds_r')
ax3.set_title("Sentiment-Rating Divergence Rate by Application")
ax3.set_ylabel("Mismatch Rate (%)")
ax3.set_xlabel("Application")
fig3_b64 = fig_to_base64(fig3)

# V4: Word Count by Star Rating
fig4, ax4 = plt.subplots(figsize=(8, 5))
sns.barplot(data=wc_by_star, x='Star_Rating', y='Word_Count', ax=ax4, palette='Blues_r')
ax4.set_title("Average Word Count vs. Star Rating")
ax4.set_ylabel("Average Word Count")
ax4.set_xlabel("Star Rating")
fig4_b64 = fig_to_base64(fig4)


# 4. Generate HTML
